-- NEW LOCAL PROPOSAL: exact eight roles/three admissions/four events; retain every pass/audit/receipt.
-- Run emergency disable first, even when this stricter scope reconciliation cannot complete.
begin;set local search_path='';set local lock_timeout='3s';set local statement_timeout='15s';
do $cleanup$
declare f jsonb;t timestamptz;changed integer;role_count integer:=0;admission_count integer;
begin
 if nullif(current_setting('vne.day07.approval_ref',true),'') is null then raise exception 'explicit_cleanup_approval_required';end if;
 if not exists(select 1 from private.qr_admission_config where singleton and project_ref='xrocuwlofxhxoxajukne' and not enabled and not synthetic_admission) then raise exception 'disable_first';end if;
 if to_regprocedure('public.vne_qr_command(jsonb)') is not null and (has_function_privilege('anon','public.vne_qr_command(jsonb)','execute') or has_function_privilege('authenticated','public.vne_qr_command(jsonb)','execute') or has_function_privilege('service_role','public.vne_qr_command(jsonb)','execute')) then raise exception 'revoke_public_API_first';end if;
 select qr_release_at into t from public.events where id='d0700000-0000-4000-8000-000000000001';if t is null then raise exception 'fixture_missing';end if;
 for f in select value from jsonb_array_elements('[{"event":"d0700000-0000-4000-8000-000000000001","tier":"d0700000-0000-4000-8000-000000000002","application":"d0700000-0000-4000-8000-000000000003","reservation":"d0700000-0000-4000-8000-000000000004","order":"d0700000-0000-4000-8000-000000000005","participation":"d0700000-0000-4000-8000-000000000006","idempotency":"d0700000-0000-4000-8000-000000000007","scannerA":"d0700000-0000-4000-8000-000000000008","scannerB":"d0700000-0000-4000-8000-000000000009","scenario":"primary-race","qrMinutes":0,"entryMinutes":1,"addressMinutes":2,"startsMinutes":5,"closesMinutes":20},{"event":"d0710000-0000-4000-8000-000000000001","tier":"d0710000-0000-4000-8000-000000000002","application":"d0710000-0000-4000-8000-000000000003","reservation":"d0710000-0000-4000-8000-000000000004","order":"d0710000-0000-4000-8000-000000000005","participation":"d0710000-0000-4000-8000-000000000006","idempotency":"d0710000-0000-4000-8000-000000000007","scannerA":"d0710000-0000-4000-8000-000000000008","scannerB":"d0710000-0000-4000-8000-000000000009","scenario":"rotation-revoke","qrMinutes":0,"entryMinutes":1,"addressMinutes":2,"startsMinutes":5,"closesMinutes":20},{"event":"d0720000-0000-4000-8000-000000000001","tier":"d0720000-0000-4000-8000-000000000002","application":"d0720000-0000-4000-8000-000000000003","reservation":"d0720000-0000-4000-8000-000000000004","order":"d0720000-0000-4000-8000-000000000005","participation":"d0720000-0000-4000-8000-000000000006","idempotency":"d0720000-0000-4000-8000-000000000007","scannerA":"d0720000-0000-4000-8000-000000000008","scannerB":"d0720000-0000-4000-8000-000000000009","scenario":"future-boundaries","qrMinutes":4,"entryMinutes":6,"addressMinutes":7,"startsMinutes":8,"closesMinutes":20},{"event":"d0730000-0000-4000-8000-000000000001","tier":"d0730000-0000-4000-8000-000000000002","application":"d0730000-0000-4000-8000-000000000003","reservation":"d0730000-0000-4000-8000-000000000004","order":"d0730000-0000-4000-8000-000000000005","participation":"d0730000-0000-4000-8000-000000000006","idempotency":"d0730000-0000-4000-8000-000000000007","scannerA":"d0730000-0000-4000-8000-000000000008","scannerB":"d0730000-0000-4000-8000-000000000009","scenario":"short-expiry","qrMinutes":0,"entryMinutes":1,"addressMinutes":2,"startsMinutes":3,"closesMinutes":8}]'::jsonb) loop
  perform 1 from public.staff_assignments where id in((f->>'scannerA')::uuid,(f->>'scannerB')::uuid) for update;
  if (select count(*) from public.staff_assignments where (id=(f->>'scannerA')::uuid and user_id='1e7259c2-ad13-43a1-b34b-cba71533e844'::uuid or id=(f->>'scannerB')::uuid and user_id='ed2433cb-bc6e-4b23-aa57-000839292ec4'::uuid) and event_id=(f->>'event')::uuid and role='scanner' and valid_from=t and valid_until=t+interval '20 minutes')<>2 then raise exception 'assignment_binding_drift';end if;
  update public.staff_assignments set revoked_at=coalesce(revoked_at,clock_timestamp()) where (id=(f->>'scannerA')::uuid and user_id='1e7259c2-ad13-43a1-b34b-cba71533e844'::uuid or id=(f->>'scannerB')::uuid and user_id='ed2433cb-bc6e-4b23-aa57-000839292ec4'::uuid) and event_id=(f->>'event')::uuid and role='scanner';get diagnostics changed=row_count;if changed<>2 then raise exception 'role_cleanup_count';end if;role_count:=role_count+changed;
  update public.events set status='archived' where id=(f->>'event')::uuid and is_synthetic and slug='day07-'||(f->>'scenario');get diagnostics changed=row_count;if changed<>1 then raise exception 'event_cleanup_binding';end if;
 end loop;
 perform 1 from private.member_admission where user_id in('15cbc7a4-92f6-48d8-abb2-ed68f7612271'::uuid,'1e7259c2-ad13-43a1-b34b-cba71533e844'::uuid,'ed2433cb-bc6e-4b23-aa57-000839292ec4'::uuid) for update;
 if (select count(*) from private.member_admission where user_id in('15cbc7a4-92f6-48d8-abb2-ed68f7612271'::uuid,'1e7259c2-ad13-43a1-b34b-cba71533e844'::uuid,'ed2433cb-bc6e-4b23-aa57-000839292ec4'::uuid) and source='day07.synthetic-20261008' and state in('admitted','revoked') and invite_id is null)<>3 then raise exception 'admission_cleanup_binding';end if;
 update private.member_admission set state='revoked',updated_at=clock_timestamp() where user_id in('15cbc7a4-92f6-48d8-abb2-ed68f7612271'::uuid,'1e7259c2-ad13-43a1-b34b-cba71533e844'::uuid,'ed2433cb-bc6e-4b23-aa57-000839292ec4'::uuid) and source='day07.synthetic-20261008' and state in('admitted','revoked') and invite_id is null;get diagnostics admission_count=row_count;if admission_count<>3 then raise exception 'admission_cleanup_count';end if;
 insert into private.audit_log(action,object_type,object_id,result,details) values('day07.synthetic_cleanup','event','d0700000-0000-4000-8000-000000000001','ok',jsonb_build_object('approvalRef',current_setting('vne.day07.approval_ref'),'rolesRevoked',role_count,'admissionsRevoked',admission_count,'evidencePreserved',true,'externalDelivery',false));
end $cleanup$;commit;
